#!/usr/bin/env python3
"""Call local ICM model workers with configurable endpoints."""

from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.error
import urllib.request
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping, Sequence


DEFAULT_WORKERS: dict[str, dict[str, Any]] = {
    "deep": {
        "api": "native-completion",
        "url": "http://<LAN_HOST>:8080/completion",
        "model": "Llama-3.3-70B-Instruct-Q4_K_M.gguf",
        "append_no_think": True,
    },
    "coder": {
        "api": "openai-chat",
        "base_url": "http://<LAN_HOST>:8081/v1",
        "model": "Qwen/Qwen2.5-Coder-7B-Instruct-GGUF:Q4_K_M",
    },
    "router": {
        "api": "openai-chat",
        "base_url": "http://<LAN_HOST>:8082/v1",
        "model": "Qwen/Qwen2.5-3B-Instruct-GGUF:Q4_K_M",
    },
    "handoff": {
        "api": "openai-chat",
        "base_url": "http://<LAN_HOST>:8083/v1",
        "model": "Qwen/Qwen2.5-7B-Instruct-GGUF:Q4_K_M",
    },
}

OPENAI_CHAT = "openai-chat"
OPENAI_COMPLETIONS = "openai-completions"
NATIVE_COMPLETION = "native-completion"
OPENAI_SUFFIXES = {
    OPENAI_CHAT: "chat/completions",
    OPENAI_COMPLETIONS: "completions",
}
SYSTEM_PROMPT = "You are a concise local AI worker. Follow the user's instructions exactly."
NATIVE_SYSTEM_PROMPT = (
    "You are a deterministic assistant. Respond only to the user's instruction. "
    "Do not continue unrelated text. Do not invent context."
)


@dataclass(frozen=True)
class WorkerSpec:
    name: str
    api: str
    model: str | None = None
    base_url: str | None = None
    url: str | None = None
    append_no_think: bool = False


@dataclass(frozen=True)
class WorkerResponse:
    status: str
    content: str
    request_url: str
    model: str | None
    finish_reason: str | None
    usage: Mapping[str, Any] | None
    timings: Mapping[str, Any] | None
    raw_response: Any
    error: str | None = None

    def metadata(self) -> dict[str, Any]:
        return {
            "status": self.status,
            "request_url": self.request_url,
            "model": self.model,
            "finish_reason": self.finish_reason,
            "usage": self.usage,
            "timings": self.timings,
            "error": self.error,
        }


def normalize_base_url(base_url: str) -> str:
    return base_url.rstrip("/")


def build_url(base_url: str, suffix: str) -> str:
    return f"{normalize_base_url(base_url)}/{suffix.lstrip('/')}"


def env_name(worker_name: str, suffix: str) -> str:
    return f"ICM_{worker_name.upper()}_{suffix}"


def env_override(worker_name: str, suffix: str) -> str | None:
    return os.environ.get(env_name(worker_name, suffix))


def resolve_worker_spec(
    worker_name: str,
    *,
    base_url: str | None = None,
    url: str | None = None,
    model: str | None = None,
    api: str | None = None,
    final_only: bool = False,
) -> WorkerSpec:
    if worker_name not in DEFAULT_WORKERS:
        raise KeyError(f"Unknown worker: {worker_name}")

    defaults = DEFAULT_WORKERS[worker_name]
    resolved_api = api or env_override(worker_name, "API") or defaults["api"]
    resolved_base_url = (
        base_url
        or env_override(worker_name, "BASE_URL")
        or defaults.get("base_url")
    )
    resolved_url = url or env_override(worker_name, "URL") or defaults.get("url")
    resolved_model = model or env_override(worker_name, "MODEL") or defaults.get("model")
    append_no_think = final_only or bool(defaults.get("append_no_think"))

    if resolved_base_url:
        resolved_base_url = normalize_base_url(resolved_base_url)

    return WorkerSpec(
        name=worker_name,
        api=resolved_api,
        model=resolved_model,
        base_url=resolved_base_url,
        url=resolved_url,
        append_no_think=append_no_think,
    )


def maybe_append_no_think(prompt: str, enabled: bool) -> str:
    if enabled and "/no_think" not in prompt:
        return prompt.rstrip() + "\n/no_think"
    return prompt


def completion_url(spec: WorkerSpec) -> str:
    if spec.api == NATIVE_COMPLETION:
        if spec.url:
            return spec.url
        raise ValueError(f"{spec.name} is missing a completion URL")

    if spec.url:
        return spec.url
    if spec.base_url:
        return build_url(spec.base_url, OPENAI_SUFFIXES[spec.api])
    raise ValueError(f"{spec.name} is missing a base URL")


def models_url(spec: WorkerSpec) -> str:
    if spec.api == NATIVE_COMPLETION:
        raise ValueError(f"{spec.name} does not expose an OpenAI-compatible /models endpoint")
    if spec.base_url:
        return build_url(spec.base_url, "models")
    if spec.url and spec.url.endswith("/chat/completions"):
        return spec.url[: -len("/chat/completions")] + "/models"
    if spec.url and spec.url.endswith("/completions"):
        return spec.url[: -len("/completions")] + "/models"
    raise ValueError(f"{spec.name} is missing a base URL for model discovery")


def build_payload(spec: WorkerSpec, prompt: str, max_tokens: int) -> dict[str, Any]:
    if spec.api == NATIVE_COMPLETION:
        formatted = (
            f"System: {NATIVE_SYSTEM_PROMPT}\n\n"
            f"User: {prompt}\n\n"
            f"Assistant:"
        )
        return {
            "prompt": formatted,
            "n_predict": max_tokens,
            "temperature": 0.2,
            "stream": False,
            "stop": ["\nUser:", "\nSystem:"],
        }

    if spec.api == OPENAI_COMPLETIONS:
        payload = {
            "prompt": prompt,
            "max_tokens": max_tokens,
            "temperature": 0.2,
            "stream": False,
        }
        if spec.model:
            payload["model"] = spec.model
        return payload

    payload = {
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": prompt},
        ],
        "max_tokens": max_tokens,
        "temperature": 0.2,
        "stream": False,
    }
    if spec.model:
        payload["model"] = spec.model
    return payload


def read_response_json(request: urllib.request.Request, timeout: int) -> Any:
    with urllib.request.urlopen(request, timeout=timeout) as response:
        return json.loads(response.read().decode("utf-8"))


def make_request(url: str, payload: dict[str, Any]) -> urllib.request.Request:
    data = json.dumps(payload).encode("utf-8")
    return urllib.request.Request(
        url,
        data=data,
        headers={"Content-Type": "application/json"},
        method="POST",
    )


def parse_native_response(result: Mapping[str, Any], request_url: str) -> WorkerResponse:
    content = result.get("content")
    if isinstance(content, str) and content:
        return WorkerResponse(
            status="ok",
            content=content,
            request_url=request_url,
            model=result.get("model"),
            finish_reason=result.get("stop_reason"),
            usage=result.get("usage"),
            timings=result.get("timings"),
            raw_response=result,
        )
    return WorkerResponse(
        status="empty",
        content="[empty content]\nRAW RESPONSE:\n" + json.dumps(result, indent=2),
        request_url=request_url,
        model=result.get("model"),
        finish_reason=result.get("stop_reason"),
        usage=result.get("usage"),
        timings=result.get("timings"),
        raw_response=result,
    )


def parse_openai_completion_response(
    result: Mapping[str, Any],
    request_url: str,
) -> WorkerResponse:
    try:
        choice = result["choices"][0]
    except (KeyError, IndexError, TypeError) as exc:
        return WorkerResponse(
            status="parse_error",
            content="[harness parse error]\n" + str(exc) + "\nRAW RESPONSE:\n" + json.dumps(result, indent=2),
            request_url=request_url,
            model=result.get("model"),
            finish_reason=None,
            usage=result.get("usage"),
            timings=result.get("timings"),
            raw_response=result,
            error=str(exc),
        )

    finish_reason = choice.get("finish_reason")
    text = choice.get("text")
    if isinstance(text, str) and text:
        return WorkerResponse(
            status="ok",
            content=text,
            request_url=request_url,
            model=result.get("model"),
            finish_reason=finish_reason,
            usage=result.get("usage"),
            timings=result.get("timings"),
            raw_response=result,
        )

    return WorkerResponse(
        status="empty",
        content="[empty content]\nRAW RESPONSE:\n" + json.dumps(result, indent=2),
        request_url=request_url,
        model=result.get("model"),
        finish_reason=finish_reason,
        usage=result.get("usage"),
        timings=result.get("timings"),
        raw_response=result,
    )


def parse_openai_chat_response(
    result: Mapping[str, Any],
    request_url: str,
) -> WorkerResponse:
    try:
        choice = result["choices"][0]
        message = choice.get("message", {})
    except (KeyError, IndexError, TypeError) as exc:
        return WorkerResponse(
            status="parse_error",
            content="[harness parse error]\n" + str(exc) + "\nRAW RESPONSE:\n" + json.dumps(result, indent=2),
            request_url=request_url,
            model=result.get("model"),
            finish_reason=None,
            usage=result.get("usage"),
            timings=result.get("timings"),
            raw_response=result,
            error=str(exc),
        )

    content = message.get("content")
    reasoning = message.get("reasoning_content")
    finish_reason = choice.get("finish_reason")

    if isinstance(content, str) and content:
        return WorkerResponse(
            status="ok",
            content=content,
            request_url=request_url,
            model=result.get("model"),
            finish_reason=finish_reason,
            usage=result.get("usage"),
            timings=result.get("timings"),
            raw_response=result,
        )

    if isinstance(reasoning, str) and reasoning:
        return WorkerResponse(
            status="reasoning_only",
            content="[reasoning_content only]\n" + reasoning,
            request_url=request_url,
            model=result.get("model"),
            finish_reason=finish_reason,
            usage=result.get("usage"),
            timings=result.get("timings"),
            raw_response=result,
        )

    return WorkerResponse(
        status="empty",
        content="[empty content]\nRAW RESPONSE:\n" + json.dumps(result, indent=2),
        request_url=request_url,
        model=result.get("model"),
        finish_reason=finish_reason,
        usage=result.get("usage"),
        timings=result.get("timings"),
        raw_response=result,
    )


def call_worker(
    worker: str | WorkerSpec,
    prompt: str,
    max_tokens: int = 512,
    *,
    timeout: int = 900,
    final_only: bool = False,
) -> WorkerResponse:
    spec = resolve_worker_spec(worker, final_only=final_only) if isinstance(worker, str) else worker
    prepared_prompt = maybe_append_no_think(prompt, spec.append_no_think)
    request_url = completion_url(spec)
    payload = build_payload(spec, prepared_prompt, max_tokens)
    request = make_request(request_url, payload)

    try:
        result = read_response_json(request, timeout)
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        return WorkerResponse(
            status="error",
            content=f"[HTTP error {exc.code}]\n{body}",
            request_url=request_url,
            model=spec.model,
            finish_reason=None,
            usage=None,
            timings=None,
            raw_response=body,
            error=f"HTTP {exc.code}",
        )
    except Exception as exc:
        return WorkerResponse(
            status="error",
            content=f"[request error]\n{exc}",
            request_url=request_url,
            model=spec.model,
            finish_reason=None,
            usage=None,
            timings=None,
            raw_response={"error": str(exc)},
            error=str(exc),
        )

    if spec.api == NATIVE_COMPLETION:
        return parse_native_response(result, request_url)
    if spec.api == OPENAI_COMPLETIONS:
        return parse_openai_completion_response(result, request_url)
    return parse_openai_chat_response(result, request_url)


def list_models(spec: WorkerSpec, timeout: int = 30) -> Any:
    request = urllib.request.Request(models_url(spec), method="GET")
    return read_response_json(request, timeout)


def write_json(path: str | Path, payload: Any) -> None:
    Path(path).write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")


def read_prompt(args: argparse.Namespace) -> str:
    if args.prompt_file:
        return Path(args.prompt_file).read_text(encoding="utf-8")
    if args.prompt:
        return " ".join(args.prompt)
    return sys.stdin.read()


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Call local ICM model workers directly.")
    parser.add_argument(
        "worker",
        choices=DEFAULT_WORKERS.keys(),
        help="Worker to call: deep, coder, router, or handoff",
    )
    parser.add_argument(
        "--api",
        choices=(NATIVE_COMPLETION, OPENAI_CHAT, OPENAI_COMPLETIONS),
        help="Override the worker API style.",
    )
    parser.add_argument("--base-url", help="Override the worker base URL, such as http://localhost:8083/v1")
    parser.add_argument("--url", help="Override the exact completion URL.")
    parser.add_argument("--model", help="Override the model name sent to the worker.")
    parser.add_argument("--prompt-file", help="Read the prompt from a file instead of argv/stdin.")
    parser.add_argument(
        "--max-tokens",
        type=int,
        default=512,
        help="Maximum response tokens.",
    )
    parser.add_argument(
        "--timeout",
        type=int,
        default=900,
        help="HTTP timeout in seconds.",
    )
    parser.add_argument(
        "--final-only",
        action="store_true",
        help="Append /no_think when the prompt does not already include it.",
    )
    parser.add_argument(
        "--list-models",
        action="store_true",
        help="List models for an OpenAI-compatible worker and exit.",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Print the response body plus metadata as JSON.",
    )
    parser.add_argument("--metadata-out", help="Write response metadata to a JSON file.")
    parser.add_argument("--raw-response-out", help="Write the raw response payload to a JSON file.")
    parser.add_argument(
        "prompt",
        nargs="*",
        help="Prompt text. If omitted, prompt is read from stdin.",
    )
    return parser


def parse_args(parser: argparse.ArgumentParser, argv: Sequence[str] | None) -> argparse.Namespace:
    if hasattr(parser, "parse_intermixed_args"):
        return parser.parse_intermixed_args(argv)
    return parser.parse_args(argv)


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parse_args(parser, argv)
    spec = resolve_worker_spec(
        args.worker,
        base_url=args.base_url,
        url=args.url,
        model=args.model,
        api=args.api,
        final_only=args.final_only,
    )

    if args.list_models:
        try:
            print(json.dumps(list_models(spec, timeout=args.timeout), indent=2))
            return 0
        except Exception as exc:
            print(f"[request error]\n{exc}")
            return 1

    prompt = read_prompt(args)
    if not prompt.strip():
        parser.error("No prompt provided.")

    response = call_worker(
        spec,
        prompt,
        args.max_tokens,
        timeout=args.timeout,
    )

    if args.metadata_out:
        write_json(args.metadata_out, response.metadata())
    if args.raw_response_out:
        write_json(args.raw_response_out, response.raw_response)

    if args.json:
        output = dict(response.metadata())
        output["content"] = response.content
        print(json.dumps(output, indent=2))
    else:
        print(response.content)

    return 0 if response.status in {"ok", "reasoning_only"} else 1


if __name__ == "__main__":
    raise SystemExit(main())
